setcpm(66 / 4)

let A = "<Dm9 Bb^7 Gm9 Am7 Dm9 Bb^7 F^7 Am7>"
let B = "<Gm9 Dm9 Bb^7 Am7 Gm9 F^7 Am7 Dm9>"
